package com.travel.food; public record FoodView(Long id,String name,String address,double longitude,double latitude,Double price,Double rating,String openingHours,String link,String notes,String status,Long placeId){static FoodView from(Food f){return new FoodView(f.id,f.name,f.address,f.longitude,f.latitude,f.price,f.rating,f.openingHours,f.link,f.notes,f.status,f.place==null?null:f.place.getId());}}
